type BaseParserType<'input, I> = BaseParser<
    'input,
    GQLParserExt<'input>,
    I,
    GQLParserContextType,
    dyn GQLListener<'input> + 'input,
>;

type TokenType<'input> = <LocalTokenFactory<'input> as TokenFactory<'input>>::Tok;
pub type LocalTokenFactory<'input> = CommonTokenFactory;

pub type GQLTreeWalker<'input, 'a> =
ParseTreeWalker<'input, 'a, GQLParserContextType, dyn GQLListener<'input> + 'a>;

/// Parser for GQL grammar
pub struct GQLParser<'input, I, H>
where
    I: TokenStream<'input, TF=LocalTokenFactory<'input>> + TidAble<'input>,
    H: ErrorStrategy<'input, BaseParserType<'input, I>>,
{
    base: BaseParserType<'input, I>,
    interpreter: Arc<ParserATNSimulator>,
    _shared_context_cache: Box<PredictionContextCache>,
    pub err_handler: H,
}

impl<'input, I, H> GQLParser<'input, I, H>
where
    I: TokenStream<'input, TF=LocalTokenFactory<'input>> + TidAble<'input>,
    H: ErrorStrategy<'input, BaseParserType<'input, I>>,
{
    pub fn get_serialized_atn() -> &'static str {
        _serializedATN
    }

    pub fn set_error_strategy(&mut self, strategy: H) {
        self.err_handler = strategy
    }

    pub fn with_strategy(input: I, strategy: H) -> Self {
        antlr_rust::recognizer::check_version("0", "3");
        let interpreter = Arc::new(ParserATNSimulator::new(
            _ATN.clone(),
            _decision_to_DFA.clone(),
            _shared_context_cache.clone(),
        ));
        Self {
            base: BaseParser::new_base_parser(
                input,
                Arc::clone(&interpreter),
                GQLParserExt {
                    _pd: Default::default(),
                },
            ),
            interpreter,
            _shared_context_cache: Box::new(PredictionContextCache::new()),
            err_handler: strategy,
        }
    }
}

type DynStrategy<'input, I> = Box<dyn ErrorStrategy<'input, BaseParserType<'input, I>> + 'input>;

impl<'input, I> GQLParser<'input, I, DynStrategy<'input, I>>
where
    I: TokenStream<'input, TF=LocalTokenFactory<'input>> + TidAble<'input>,
{
    pub fn with_dyn_strategy(input: I) -> Self {
        Self::with_strategy(input, Box::new(DefaultErrorStrategy::new()))
    }
}

impl<'input, I> GQLParser<'input, I, DefaultErrorStrategy<'input, GQLParserContextType>>
where
    I: TokenStream<'input, TF=LocalTokenFactory<'input>> + TidAble<'input>,
{
    pub fn new(input: I) -> Self {
        Self::with_strategy(input, DefaultErrorStrategy::new())
    }
}

/// Trait for monomorphized trait object that corresponds to the nodes of parse tree generated for GQLParser
pub trait GQLParserContext<'input>:
    for<'x> Listenable<dyn GQLListener<'input> + 'x>
+ for<'x> Visitable<dyn GQLVisitor<'input> + 'x>
+ ParserRuleContext<'input, TF=LocalTokenFactory<'input>, Ctx=GQLParserContextType>
{}

antlr_rust::coerce_from! { 'input : GQLParserContext<'input> }

impl<'input, 'x, T> VisitableDyn<T> for dyn GQLParserContext<'input> + 'input
where
    T: GQLVisitor<'input> + 'x,
{
    fn accept_dyn(&self, visitor: &mut T) {
        self.accept(visitor as &mut (dyn GQLVisitor<'input> + 'x))
    }
}

impl<'input> GQLParserContext<'input> for TerminalNode<'input, GQLParserContextType> {}
impl<'input> GQLParserContext<'input> for ErrorNode<'input, GQLParserContextType> {}

antlr_rust::tid! { impl<'input> TidAble<'input> for dyn GQLParserContext<'input> + 'input }

antlr_rust::tid! { impl<'input> TidAble<'input> for dyn GQLListener<'input> + 'input }

