//------------------- nonReservedWords ----------------
pub type NonReservedWordsContextAll<'input> = NonReservedWordsContext<'input>;

pub type NonReservedWordsContext<'input> =
BaseParserRuleContext<'input, NonReservedWordsContextExt<'input>>;

#[derive(Clone)]
pub struct NonReservedWordsContextExt<'input> {
    ph: PhantomData<&'input str>,
}

impl<'input> GQLParserContext<'input> for NonReservedWordsContext<'input> {}

impl<'input, 'a> Listenable<dyn GQLListener<'input> + 'a> for NonReservedWordsContext<'input> {
    fn enter(&self, listener: &mut (dyn GQLListener<'input> + 'a)) {
        listener.enter_every_rule(self);
        listener.enter_nonReservedWords(self);
    }
    fn exit(&self, listener: &mut (dyn GQLListener<'input> + 'a)) {
        listener.exit_nonReservedWords(self);
        listener.exit_every_rule(self);
    }
}

impl<'input, 'a> Visitable<dyn GQLVisitor<'input> + 'a> for NonReservedWordsContext<'input> {
    fn accept(&self, visitor: &mut (dyn GQLVisitor<'input> + 'a)) {
        visitor.visit_nonReservedWords(self);
    }
}

impl<'input> CustomRuleContext<'input> for NonReservedWordsContextExt<'input> {
    type TF = LocalTokenFactory<'input>;
    type Ctx = GQLParserContextType;
    fn get_rule_index(&self) -> usize {
        RULE_nonReservedWords
    }
    //fn type_rule_index() -> usize where Self: Sized { RULE_nonReservedWords }
}
antlr_rust::tid! {NonReservedWordsContextExt<'a>}

impl<'input> NonReservedWordsContextExt<'input> {
    fn new(
        parent: Option<Rc<dyn GQLParserContext<'input> + 'input>>,
        invoking_state: isize,
    ) -> Rc<NonReservedWordsContextAll<'input>> {
        Rc::new(BaseParserRuleContext::new_parser_ctx(
            parent,
            invoking_state,
            NonReservedWordsContextExt { ph: PhantomData },
        ))
    }
}

